/**
 * Source Serif 4 (SIL Open Font License 1.1), latin subset, variable wght
 * 200-900 — upright + italic, as served by Google Fonts.
 *
 * Embedded as base64 rather than linked: the Remotion render runs in headless
 * Chrome with no network access to fonts.googleapis.com, so a <link> would
 * silently fall back to a system serif and the render would look wrong with no
 * error. Same reason as fonts-data.ts.
 *
 * Owner picked Source Serif 4 over EB Garamond after seeing both on a phone.
 */
export const SOURCE_SERIF_4_LATIN_WOFF2_BASE64 =
  ""

export const SOURCE_SERIF_4_LATIN_ITALIC_WOFF2_BASE64 =
  ""
